{"description":"Fit Lorentzian to 2D band with linear background","cmd":"cd /app && python3 << 'EOF'
import numpy as np
from scipy.optimize import curve_fit
x=[];y=[]
with open('graphene.dat') as f:
    for line in f:
        p=line.strip().split('\t')
        x.append(float(p[0].replace(',','.')))
        y.append(float(p[1].replace(',','.')))
x=np.array(x);y=np.array(y)

def lor_lin(x, x0, g, A, off, m):
    return off + m*x + A*g**2/((x-x0)**2+g**2)

for lo,hi,lab in [(15600,16900,'15600-16900'), (15700,16800,'15700-16800'), (15900,16600,'15900-16600')]:
    m=(x>=lo)&(x<=hi)
    xx=x[m]; yy=y[m]
    try:
        popt,_=curve_fit(lor_lin, xx, yy, p0=[16250,200,1500,10000,0.4], maxfev=20000)
        res=yy-lor_lin(xx,*popt)
        print(f'[{lab}] x0={popt[0]:.2f} gamma={popt[1]:.2f} A={popt[2]:.2f} off={popt[3]:.2f} slope={popt[4]:.4f} rmse={np.sqrt(np.mean(res**2)):.1f} maxres={np.max(np.abs(res)):.1f}')
    except Exception as e:
        print(lab, 'fail', e)
EOF"}

{"description":"Fit Lorentzian to the G region on the laser tail","cmd":"cd /app && python3 << 'EOF'
import numpy as np
from scipy.optimize import curve_fit
x=[];y=[]
with open('graphene.dat') as f:
    for line in f:
        p=line.strip().split('\t')
        x.append(float(p[0].replace(',','.')))
        y.append(float(p[1].replace(',','.')))
x=np.array(x);y=np.array(y)

def lor_lin(x, x0, g, A, off, m):
    return off + m*x + A*g**2/((x-x0)**2+g**2)

for lo,hi,lab in [(17300,17850,'17300-17850'), (17400,17950,'17400-17950'), (17000,18000,'17000-18000')]:
    m=(x>=lo)&(x<=hi)
    xx=x[m]; yy=y[m]
    # x0 around 17560 (G), small width, A positive
    try:
        popt,_=curve_fit(lor_lin, xx, yy, p0=[17560,40,300,50000,0.0], maxfev=20000,
                         bounds=([17400,1,-2000,-1e5,-10],[17800,200,5000,1e5,0]))
        res=yy-lor_lin(xx,*popt)
        print(f'[{lab}] x0={popt[0]:.2f} gamma={popt[1]:.2f} A={popt[2]:.2f} off={popt[3]:.2f} slope={popt[4]:.4f} rmse={np.sqrt(np.mean(res**2)):.1f}')
        for a,b in zip(xx,yy): print('  %.2f %8.2f'%(a,b))
    except Exception as e:
        print(lab,'fail',e)
EOF"}

