{"description":"Fit the other candidate peaks (10289, 6329, 3745)","cmd":"cd /app && python3 << 'EOF'
import numpy as np
from scipy.optimize import curve_fit
x=[];y=[]
with open('graphene.dat') as f:
    for line in f:
        p=line.strip().split('\t')
        x.append(float(p[0].replace(',','.')))
        y.append(float(p[1].replace(',','.')))
x=np.array(x);y=np.array(y)

def lor_lin(x, x0, g, A, off, m):
    return off + m*x + A*g**2/((x-x0)**2+g**2)

for xc, span, lab in [(10289.94, 900, '10289'), (6329.37, 900, '6329'), (3745.05, 700, '3745'), (16245.58, 800, '16245')]:
    lo=xc-span; hi=xc+span
    m=(x>=lo)&(x<=hi)
    xx=x[m]; yy=y[m]
